import{z as s,x as c,o,c as h,q as r,j as n,D as a,d as E,s as p,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Expert Choice 论文","description":"","frontmatter":{"title":"Expert Choice 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/expert-choice-paper.md","filePath":"llm/expert-choice-paper.md","lastUpdated":1791413859000}'),B={name:"llm/expert-choice-paper.md"};function d(C,e,A,k,m,u){const i=c("Mermaid");return o(),h("div",null,[e[2]||(e[2]=r('<h1 id="expert-choice-论文" tabindex="-1">Expert Choice 论文 <a class="header-anchor" href="#expert-choice-论文" aria-label="Permalink to &quot;Expert Choice 论文&quot;">​</a></h1><div class="epigraph"><p>让每个专家在自己的容量内挑选 token，专家维负载天然齐平；有的 token 会被抢多次，有的一次都轮不到。</p><footer>—— Zhou et al., Mixture-of-Experts with Expert Choice Routing, NeurIPS 2022</footer></div><p><a href="/llm/fedus-switch">Switch 原文</a> 是 token-choice：\\(k=1\\) 时每行取 argmax，再用容量因子 drop。Zhou、Lei、Liu 等人把矩阵转过来：<strong>每列（专家）取 top-\\(C\\)</strong>。主干 <a href="/llm/moe-expert-choice">Expert-choice 路由</a> 已写机制；本篇对照论文主张与实验边界，并提醒自回归解码的不一致是原文就必须面对的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Token-choice 的均衡靠辅助损失，失败则专家饿死或过载 drop。作者问：若约束直接写在专家配额上，还能否提高专家利用率与下游质量？分数矩阵 \\(S\\in\\mathbb{R}^{T\\times N}\\)，列上 top-\\(C\\)、\\(C\\) 由目标等价负载决定，则每个专家恰好 \\(C\\) 个 token。</p><p><span class="marginnote">术语翻译：token-choice 是「学生选课」——每个 token 自己挑最合适的专家，热门课会爆满；expert-choice 是「老师挑学生」——每个专家按配额挑自己最擅长的 token，课课满员，但可能有学生一门课都没被挑上。整篇论文就是这一次视角翻转。</span></p><p>副效应：行和不再恒等于 \\(k\\)。过分配与零覆盖是论文必须处理的对象，不是实现 bug。</p><h3 id="训练可见整段" tabindex="-1">训练可见整段 \\(T\\) <a class="header-anchor" href="#训练可见整段" aria-label="Permalink to &quot;训练可见整段 $T$&quot;">​</a></h3><p>编码器或训练期整句可见时，列 top 合法。逐步解码没有未来行。论文语境含预训练与理解任务；把它当 LLM decode 默认路由，需要近似，主干课已写。<span class="marginnote">作者名单以 Yanqi Zhou、Tao Lei、Hanxiao Liu 等为主，Google 线。引用用论文题名，不要用内部别名当文献。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="列上-top-与回退" tabindex="-1">列上 top-\\(C\\) 与回退 <a class="header-anchor" href="#列上-top-与回退" aria-label="Permalink to &quot;列上 top-$C$ 与回退&quot;">​</a></h3><p>对 \\(S\\) 每列取 top-\\(C\\)，只在选中位置做专家 FFN。负载统计变为近乎常数，辅助损失可以减弱。对零覆盖 token 的回退（残差或强制分配）影响质量，属于实验选择。评测对比同参数 / 同计算下的 token-choice。覆盖率与下游应同时报，否则「利用率上升」只是负载直方图好看。</p>',12)),(o(),n(l,null,{default:a(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%88%86%E6%95%B0%20T%20%E4%B9%98%20N%22%5D%20--%3E%20COL%5B%22%E6%AF%8F%E5%88%97%20top-C%22%5D%0A%20%20COL%20--%3E%20BAL%5B%22%E4%B8%93%E5%AE%B6%E8%B4%9F%E8%BD%BD%E9%BD%90%22%5D%0A%20%20COL%20--%3E%20ROW%5B%22token%20%E8%BF%87%E5%88%86%E9%85%8D%E6%88%96%E9%9B%B6%E8%A6%86%E7%9B%96%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,"竞争从「token 抢热专家」改为「专家抢高分 token」。利用率上升是直接推论；专业化方向取决于分数是否分列归一。论文用实验支持质量，而不是只报负载直方图。读者应同时看下游与覆盖率——原文若偏重利用率，工程复现仍要补覆盖日志。",-1)),e[5]||(e[5]=t("p",null,"与 Switch 的 drop 伤害对象不同：Switch 丢过载门口的人；EC 丢无人认领的人。长尾语言风险在论文的通用语料平均里可能被稀释。",-1)),(o(),n(l,null,{default:a(()=>[p(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TC%5B%22Token-choice%EF%BC%9Atoken%20%E6%8C%91%E4%B8%93%E5%AE%B6%EF%BC%88%E6%AF%8F%E8%A1%8C%20top-k%EF%BC%89%22%5D%20--%3E%20TCD%5B%22%E4%B8%93%E5%AE%B6%E8%BF%87%E8%BD%BD%EF%BC%9A%E4%B8%A2%E6%8E%92%E9%98%9F%E7%9A%84%20token%22%5D%0A%20%20EC%5B%22Expert-choice%EF%BC%9A%E4%B8%93%E5%AE%B6%E6%8C%91%20token%EF%BC%88%E6%AF%8F%E5%88%97%20top-C%EF%BC%89%22%5D%20--%3E%20ECA%5B%22%E7%83%AD%20token%20%E8%A2%AB%E5%A4%9A%E4%B8%AA%E4%B8%93%E5%AE%B6%E6%8A%A2%EF%BC%88%E8%BF%87%E5%88%86%E9%85%8D%EF%BC%89%22%5D%0A%20%20EC%20--%3E%20ECB%5B%22%E5%86%B7%20token%20%E6%97%A0%E4%BA%BA%E8%AE%A4%E9%A2%86%EF%BC%88%E9%9B%B6%E8%A6%86%E7%9B%96%EF%BC%89%E2%86%92%20%E5%9B%9E%E9%80%80%20%2F%20%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20TCD%20--%3E%20CMP%5B%22%E4%B8%A4%E7%A7%8D%E8%B7%AF%E7%94%B1%E4%B8%A2%E7%9A%84%E5%AF%B9%E8%B1%A1%E4%B8%8D%E5%90%8C%EF%BC%8C%E7%9B%91%E6%8E%A7%E6%8C%87%E6%A0%87%E4%B9%9F%E4%B8%8D%E5%90%8C%22%5D%0A%20%20ECA%20--%3E%20CMP%0A%20%20ECB%20--%3E%20CMP%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<p><span class="marginnote">常见误区：把「零覆盖 token」当成实现 bug。它恰恰是 expert-choice 的定义性副作用——专家各挑各的，没有任何机制保证每个 token 都被认领。工程上必须显式写回退策略（残差直通或强制分配），并把零覆盖率当一等指标监控。</span></p><p><span class="marginnote">容量 \\(C\\) 在 EC 里是吃满配额，在 Switch 里是上限。同一符号，对照时必须说清等式还是不等式。</span></p><h3 id="在对照链中的位置" tabindex="-1">在对照链中的位置 <a class="header-anchor" href="#在对照链中的位置" aria-label="Permalink to &quot;在对照链中的位置&quot;">​</a></h3><p>下一篇 z-loss 对照稳定训练；EC 本身减轻均衡损失，但不自动解决 logit 爆炸。不要把「不用辅助损失」写成 EC 的全部贡献——那是负载几何，不是数值尺度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>小 \\(T\\)（微 batch）时 top-\\(C\\) 统计崩溃。packing 跨样本会让专家跨句抢 token，论文设定若为单句 / 规范 batch，搬到 LLM packing 必须加掩码。生成任务要用 token-choice 近似，训练–推理差是一等限制。</p><p><span class="marginnote">为什么重要：训练时整句可见，专家才能「看着全句挑 token」；生成时下一个词还没出现，列 top-\\(C\\) 根本没得挑。这是 EC 不能直接用于自回归解码、工业界默认仍是 token-choice 的根本原因——不是没人试，而是因果结构不允许。</span></p><p>NeurIPS 2022 的数字绑定他们的模型与数据。Mixtral / DeepSeek 产品默认仍是 token-choice，说明工业默认并未翻转。对照价值是指出负载约束可以写在另一条轴上。</p><p><span class="marginnote">题名 <em>Mixture-of-Experts with Expert Choice Routing</em>。会议 NeurIPS 2022。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原文把路由改为专家侧 top-\\(C\\)，专家负载齐、token 覆盖不齐。</li><li>针对 token-choice + 辅助损失 + drop 的配方提出替代几何。</li><li>自回归 decode 不能原样执行列选择。</li><li>利用率不是唯一验收；须看零覆盖与下游。</li><li>出处：Zhou 等，NeurIPS 2022。</li></ul>',11))])}const D=s(B,[["render",d]]);export{f as __pageData,D as default};
